.repeating_linear => |g| {
f = "repeating-linear-gradient(";
            prefix = g.vendor_prefix;
},
.radial => |g| {
f = "radial-gradient(";
            prefix = g.vendor_prefix;
},
.repeating_radial => |g| {
f = "repeating-radial-gradient(";
            prefix = g.vendor_prefix;
},
.conic => {
f = "conic-gradient(";
},
.repeating_conic => {
f = "repeating-conic-gradient(";
},
.@"webkit-gradient" => {
f = "-webkit-gradient(";
},
