            .angle => |*angle| try angle.toCss(dest),
            .horizontal => |*k| {
                if (dest.minify) {
                    try dest.writeStr(switch (k.*) {
                        .left => "270deg",
                        .right => "90deg",
                    });
                } else {
                    if (!is_prefixed) {
                        try dest.writeStr("to ");
                    }
                    try k.toCss(dest);
                }
            },
            .vertical => |*k| {
                if (dest.minify) {
                    try dest.writeStr(switch (k.*) {
                        .top => "0deg",
                        .bottom => "180deg",
                    });
                } else {
                    if (!is_prefixed) {
                        try dest.writeStr("to ");
                    }
                    try k.toCss(dest);
                }
            },
            .corner => |*c| {
                if (!is_prefixed) {
                    try dest.writeStr("to ");
                }
                try c.vertical.toCss(dest);
                try dest.writeChar(' ');
                try c.horizontal.toCss(dest);
            },
        }
    }
