        pub fn getFallback(this: *const @This(), allocator: Allocator, kind: css.ColorFallbackKind) GradientItem(D) {
            return switch (this.*) {
                .color_stop => |*stop| .{
                    .color_stop = .{
                        .color = stop.color.getFallback(allocator, kind),
                        .position = if (stop.position) |*p| p.deepClone(allocator) else null,
                    },
